-- ══════════════════════════════════════════════════════════════════
-- 14. ตรวจสอบผลลัพธ์
-- ══════════════════════════════════════════════════════════════════

-- 14.1 รายการคำสั่งซื้อทั้งหมดพร้อมสถานะการชำระเงิน/จัดส่ง และรายการหนังสือ
SELECT
    o.OrderID,
    CONVERT(varchar(10), o.OrderDate, 120) AS OrderDate,
    c.CustomerName,
    p.Amount,
    p.PaymentMethod,
    p.PaymentStatus,
    s.Status AS ShipmentStatus,
    STRING_AGG(CONCAT(b.BookName, N' x', od.Quantity), N', ') AS Items
FROM dbo.Orders o
JOIN dbo.Customer     c  ON c.CustomerID  = o.CustomerID
JOIN dbo.Order_Detail od ON od.OrderID    = o.OrderID
JOIN dbo.Book         b  ON b.ISBN        = od.ISBN
LEFT JOIN dbo.Payment  p ON p.OrderID     = o.OrderID
LEFT JOIN dbo.Shipment s ON s.OrderID     = o.OrderID
GROUP BY o.OrderID, o.OrderDate, c.CustomerName, p.Amount, p.PaymentMethod, p.PaymentStatus, s.Status
ORDER BY o.OrderID;
GO

-- 14.2 สรุปจำนวนแถวในแต่ละตาราง (ตรวจว่านำเข้าข้อมูลครบ)
SELECT 'Customer'     AS TableName, COUNT(*) AS RowCount FROM dbo.Customer      UNION ALL
SELECT 'Category',           COUNT(*) FROM dbo.Category      UNION ALL
SELECT 'Author',             COUNT(*) FROM dbo.Author        UNION ALL
SELECT 'Book',                COUNT(*) FROM dbo.Book          UNION ALL
SELECT 'Book_Category',      COUNT(*) FROM dbo.Book_Category UNION ALL
SELECT 'Book_Author',        COUNT(*) FROM dbo.Book_Author   UNION ALL
SELECT 'Orders',              COUNT(*) FROM dbo.Orders        UNION ALL
SELECT 'Order_Detail',       COUNT(*) FROM dbo.Order_Detail  UNION ALL
SELECT 'Payment',             COUNT(*) FROM dbo.Payment       UNION ALL
SELECT 'Shipment',            COUNT(*) FROM dbo.Shipment      UNION ALL
SELECT 'SystemUser',         COUNT(*) FROM dbo.SystemUser;
GO

-- 14.3 ตรวจสอบว่ายอดในตาราง Payment ตรงกับผลรวม Quantity*UnitPrice ของแต่ละออเดอร์ทุกใบ
SELECT o.OrderID, p.Amount AS PaymentAmount, SUM(od.Quantity * od.UnitPrice) AS CalculatedTotal,
       CASE WHEN p.Amount = SUM(od.Quantity * od.UnitPrice) THEN N'OK' ELSE N'MISMATCH' END AS CheckResult
FROM dbo.Orders o
JOIN dbo.Order_Detail od ON od.OrderID = o.OrderID
JOIN dbo.Payment p       ON p.OrderID  = o.OrderID
GROUP BY o.OrderID, p.Amount
ORDER BY o.OrderID;
GO

-- 14.4 รายชื่อตารางทั้งหมดในฐานข้อมูล
SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES
WHERE TABLE_SCHEMA = 'dbo' ORDER BY TABLE_NAME;
GO

-- 14.5 ตรวจสอบว่าสลิป/ใบเสร็จสอดคล้องกับช่องทางชำระเงิน (เงินสด=ไม่มี, โอน/บัตร=ควรมีถ้ายืนยัน/รอตรวจสอบแล้ว)
SELECT PaymentID, OrderID, PaymentMethod, PaymentStatus,
       CASE WHEN SlipImage IS NOT NULL THEN N'มีสลิป' ELSE N'ไม่มี' END AS SlipCheck
FROM dbo.Payment ORDER BY OrderID;
GO

-- 14.6 ตรวจสอบว่า Payment กับ Shipment สอดคล้องกัน (ไม่มีคำสั่งซื้อที่ยังไม่ยืนยันเงินแต่จัดส่งไปแล้ว)
SELECT o.OrderID, p.PaymentStatus, s.Status AS ShipmentStatus,
       CASE WHEN p.PaymentStatus IN (N'รอชำระ', N'รอตรวจสอบ') AND s.Status <> N'รอจัดส่ง'
            THEN N'MISMATCH — จัดส่งไปแล้วทั้งที่ยังไม่ยืนยันเงิน'
            WHEN p.PaymentStatus = N'ยืนยันแล้ว' AND s.Status = N'รอจัดส่ง'
            THEN N'MISMATCH — เงินยืนยันแล้วแต่ยังไม่เริ่มจัดส่ง'
            ELSE N'OK' END AS ConsistencyCheck
FROM dbo.Orders o
JOIN dbo.Payment p  ON p.OrderID = o.OrderID
JOIN dbo.Shipment s ON s.OrderID = o.OrderID
ORDER BY o.OrderID;
GO